// Core runs the same agent and map as the installed Explorer. Only browser
// calls cross the connection. The first frame comes from application.start.
import {
  explorePlanningTarget,
  exploreWithDriver,
} from "./browser-explorer.mjs";
import { browserEnvironmentInstruction } from "./agent-context.mjs";

export function exploreConnectedBrowser(
  options,
  { initial, catalog, platform, invoke },
) {
  let calls = [];
  let browserSignal = options.signal;
  const take = (type, name) => {
    const index = calls.findIndex(
      (call) => call.type === type && (!name || call.name === name),
    );
    if (index < 0) throw Error("The model call is unavailable.");
    return calls.splice(index, 1)[0];
  };
  return explorePlanningTarget(
    {
      ...options,
      requestResponses: async (body, signal) => {
        const response = await options.requestResponses(body, signal);
        if (!response.ok) return response;
        const output = await response.json();
        calls = (output.output ?? []).filter(
          (call) =>
            call.type === "computer_call" || call.type === "function_call",
        );
        return Response.json(output, { status: response.status });
      },
    },
    (native) =>
      exploreWithDriver({
        ...native,
        entryPoint: native.target.initialURL,
        environmentInstruction: () =>
          browserEnvironmentInstruction({ headless: false, platform }),
        cleanup: {},
        createDriver: () => ({
          start: async (_, startDeadline) => {
            browserSignal = startDeadline(native.timeLimitMs ?? 300000);
            return initial;
          },
          wait: (operation) => operation,
          close: async () => {},
          computer: ({ captureFrame, observe }) => {
            // The SDK invokes each primitive, then screenshot once per call. The
            // Client executes the original ordered batch and captures its result.
            const deferToClient = () => native.beforeBrowserAction?.();
            return {
              environment: "browser",
              dimensions: [1280, 720],
              click: deferToClient,
              doubleClick: deferToClient,
              drag: deferToClient,
              keypress: deferToClient,
              move: deferToClient,
              scroll: deferToClient,
              type: deferToClient,
              wait: deferToClient,
              screenshot: () => {
                const call = take("computer_call");
                return observe(
                  "computer_call",
                  { callId: call.call_id },
                  async () =>
                    captureFrame((await invoke(call, browserSignal)).frame),
                );
              },
            };
          },
          tools: ({ fn, observe, snapshot, capture }) =>
            catalog
              .filter((tool) => tool.type === "function")
              .map((tool) =>
                fn(
                  tool.name,
                  tool.description,
                  tool.parameters.properties,
                  (args) =>
                    observe(tool.name, args, async () => {
                      const reply = await invoke(
                        take("function_call", tool.name),
                        browserSignal,
                      );
                      const result =
                        tool.name === "inspect_page"
                          ? await snapshot(undefined, reply.value)
                          : reply.value;
                      const content = [
                        {
                          type: "text",
                          text: JSON.stringify({
                            result,
                            page: reply.frame?.page,
                            capturedAt: reply.frame?.capturedAt,
                            pendingBrowserDialog: reply.dialog,
                          }),
                        },
                      ];
                      if (reply.frame)
                        content.push({
                          type: "image",
                          image:
                            "data:image/png;base64," +
                            (await capture(reply.frame)),
                          detail: "original",
                        });
                      return content;
                    }),
                ),
              ),
        }),
      }),
  );
}
